const fs = require('node:fs');
const path = require('node:path');

const root = process.cwd();
const reportPath = path.join(root, 'qa-results', 'hero-composition', 'hero-composition-report.json');
const contractPath = path.join(root, 'qa', 'viewport-audit', 'hero-composition-contract.json');
const candidateDir = path.join(root, 'qa', 'viewport-audit', 'candidates');
const candidatePath = path.join(candidateDir, 'hero-portrait360-v2.css');
const outDir = path.join(root, 'qa-results', 'hero-tuning', 'portrait360');
const jsonOut = path.join(outDir, 'portrait360-calibration.json');
const mdOut = path.join(outDir, 'portrait360-calibration.md');

const readJson = (filePath) => JSON.parse(fs.readFileSync(filePath, 'utf8'));
const round = (value) => Math.round(value * 100) / 100;
const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
const median = (values) => {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
};

if (!fs.existsSync(reportPath)) {
  console.error(`Missing composition report: ${reportPath}`);
  console.error('Run npm run qa:hero:composition:portrait360 first.');
  process.exit(1);
}
if (!fs.existsSync(contractPath)) {
  console.error(`Missing composition contract: ${contractPath}`);
  process.exit(1);
}

const report = readJson(reportPath);
const contract = readJson(contractPath);
const rows = (report.results || []).filter((item) => item.orientation === 'portrait' && item.width === 360);

if (!rows.length) {
  console.error('The current composition report does not contain 360px portrait cases.');
  console.error('Run npm run qa:hero:composition:portrait360 first.');
  process.exit(1);
}

const gapPolicy = contract.portrait.gaps.scrollToImage;

// We intentionally derive visual/image start from scroll geometry instead of
// device names. The portrait composition contract says the portrait/shape must
// begin AFTER the scroll with a bounded gap.
//
// Only use cases that are already on the Step-12 grid path. The 801/802 legacy
// cliff is excluded from calibration and then repaired by making the candidate
// architecture apply to the full 360px portrait family.
const gridRows = rows.filter((item) => item.dom?.computed?.heroDisplay === 'grid');
const severeRows = gridRows.filter((item) => item.height <= 680 && item.dom?.scroll?.found);
const visibleRows = gridRows.filter((item) => item.height >= 681 && item.dom?.scroll?.found && item.dom?.bubble?.display !== 'none');

const deriveStart = (items, preferredGap) => {
  const bottoms = items
    .map((item) => item.dom?.scroll?.bottom)
    .filter(Number.isFinite);
  if (!bottoms.length) return null;

  // A single fixed visual start is feasible when it is at least idealMin after
  // the latest scroll-bottom and no more than idealMax after the earliest one.
  const feasibleMin = Math.max(...bottoms) + gapPolicy.idealMin;
  const feasibleMax = Math.min(...bottoms) + gapPolicy.idealMax;
  const medianBottom = median(bottoms);

  let recommended = medianBottom + preferredGap;
  if (feasibleMin <= feasibleMax) recommended = clamp(recommended, feasibleMin, feasibleMax);
  else recommended = Math.max(...bottoms) + preferredGap;

  // Round to a stable whole CSS pixel for the candidate stylesheet.
  recommended = Math.round(recommended);

  return {
    count: bottoms.length,
    scrollBottomMin: round(Math.min(...bottoms)),
    scrollBottomMax: round(Math.max(...bottoms)),
    feasibleMin: round(feasibleMin),
    feasibleMax: round(feasibleMax),
    preferredGap,
    recommended,
    predictedGapMin: round(recommended - Math.max(...bottoms)),
    predictedGapMax: round(recommended - Math.min(...bottoms)),
  };
};

const severe = deriveStart(severeRows, 26);
const visible = deriveStart(visibleRows, 24);

if (!severe || !visible) {
  console.error('Could not derive both severe and bubble-visible calibration groups from the current report.');
  process.exit(1);
}

const css = `/* =========================================================\n   AUTO-GENERATED QA CANDIDATE — HERO PORTRAIT 360 V2\n   Generated by qa:hero:calibrate:portrait360\n\n   Do not paste this into hero.css yet.\n   It is injected by Playwright after the legacy stylesheet so we\n   can validate the V2 composition without destroying old work.\n\n   Derived visual starts:\n   severe/extreme (<=680px): ${severe.recommended}px\n   bubble-visible (>680px):  ${visible.recommended}px\n   ========================================================= */\n\n@media (max-width: 360px) and (orientation: portrait) {\n  .hero {\n    display: grid !important;\n    grid-template-columns: 1fr !important;\n    grid-template-rows:\n      auto\n      auto\n      auto\n      auto\n      clamp(18px, 3.5svh, 28px)\n      minmax(0, 1fr) !important;\n\n    --hero-v2-image-start: ${visible.recommended}px;\n  }\n\n  .heroSection {\n    display: contents !important;\n  }\n\n  .heroTitle {\n    grid-column: 1 !important;\n    grid-row: 1 !important;\n    justify-self: center !important;\n    margin-top: clamp(24px, 5svh, 40px) !important;\n    margin-bottom: clamp(16px, 2.4svh, 20px) !important;\n  }\n\n  .certifications {\n    grid-column: 1 !important;\n    grid-row: 2 !important;\n    justify-self: stretch !important;\n    margin-bottom: clamp(16px, 2.5svh, 20px) !important;\n  }\n\n  .bubbleContainer {\n    display: flex !important;\n    grid-column: 1 !important;\n    grid-row: 3 !important;\n    justify-self: center !important;\n    align-self: start !important;\n    transform: none !important;\n    width: min(92%, 330px) !important;\n    gap: 8px !important;\n    margin: 0 0 clamp(10px, 1.8svh, 14px) !important;\n  }\n\n  .bubble {\n    flex: 1 1 auto !important;\n    width: auto !important;\n    min-width: 0 !important;\n    height: auto !important;\n    white-space: nowrap !important;\n    font-size: 11px !important;\n    padding: 8px 10px !important;\n  }\n\n  .bubbleContainer img {\n    flex: 0 0 32px !important;\n    width: 32px !important;\n    height: 32px !important;\n  }\n\n  .scroll {\n    grid-column: 1 !important;\n    grid-row: 4 !important;\n    justify-self: center !important;\n    align-self: start !important;\n    margin: 0 !important;\n  }\n\n  .scroll > svg {\n    transform: none !important;\n  }\n\n  /*\n   * Preserve Lama Dev's bottom-anchored visual layer, but control\n   * where it starts by deriving its HEIGHT from the Hero height.\n   * This avoids the legacy 55% -> 40% cliff around 667/668px.\n   */\n  .bg {\n    top: auto !important;\n    bottom: 0 !important;\n    height: calc(100% - var(--hero-v2-image-start)) !important;\n  }\n\n  .contactButtonLink {\n    grid-column: 1 !important;\n    grid-row: 6 !important;\n    justify-self: end !important;\n    align-self: end !important;\n    margin: 0 !important;\n    padding: 18px !important;\n    padding-right: max(18px, env(safe-area-inset-right, 0px)) !important;\n    padding-bottom: max(18px, env(safe-area-inset-bottom, 0px)) !important;\n    z-index: 1 !important;\n  }\n\n  .contactButton {\n    margin: 0 !important;\n  }\n\n  .socials {\n    position: absolute !important;\n    top: 0 !important;\n    right: var(--page-gutter) !important;\n  }\n}\n\n@media (max-width: 360px) and (max-height: 680px) and (orientation: portrait) {\n  .hero {\n    --hero-v2-image-start: ${severe.recommended}px;\n  }\n\n  .bubbleContainer {\n    display: none !important;\n  }\n}\n`;

fs.mkdirSync(candidateDir, { recursive: true });
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(candidatePath, css);

const calibration = {
  artifactType: 'hero-portrait360-calibration',
  generatedAt: new Date().toISOString(),
  sourceReport: path.relative(root, reportPath),
  sourceContract: path.relative(root, contractPath),
  inputCases: rows.length,
  gridCasesUsed: gridRows.length,
  severe,
  visible,
  excludedLegacyCliffCases: rows
    .filter((item) => item.dom?.computed?.heroDisplay !== 'grid')
    .map((item) => ({ width: item.width, height: item.height, status: item.status })),
  candidateCss: path.relative(root, candidatePath),
};
fs.writeFileSync(jsonOut, `${JSON.stringify(calibration, null, 2)}\n`);

const md = [];
md.push('# Hero portrait 360 calibration', '');
md.push(`Generated: ${calibration.generatedAt}`, '');
md.push(`Input cases: **${rows.length}**`, '');
md.push('## Derived image-start corridors', '');
md.push('| Group | Cases | Scroll-bottom range | Feasible visual-start range | Recommended | Predicted scroll→image gap |');
md.push('| --- | ---: | --- | --- | ---: | --- |');
md.push(`| Severe/extreme ≤680 | ${severe.count} | ${severe.scrollBottomMin}–${severe.scrollBottomMax}px | ${severe.feasibleMin}–${severe.feasibleMax}px | **${severe.recommended}px** | ${severe.predictedGapMin}–${severe.predictedGapMax}px |`);
md.push(`| Bubble-visible ≥681 | ${visible.count} | ${visible.scrollBottomMin}–${visible.scrollBottomMax}px | ${visible.feasibleMin}–${visible.feasibleMax}px | **${visible.recommended}px** | ${visible.predictedGapMin}–${visible.predictedGapMax}px |`, '');
md.push('## Important architecture change', '');
md.push('The candidate does **not** use legacy `.bg { height: 55%/40% }` percentages. It preserves the bottom anchor and uses:', '');
md.push('```css');
md.push('height: calc(100% - var(--hero-v2-image-start));');
md.push('```', '');
md.push('This directly controls the scroll→image relationship and removes the measured 664→668 percentage cliff.', '');
md.push('## Next command', '');
md.push('```powershell');
md.push('npm run qa:hero:composition:portrait360:candidate');
md.push('```');
fs.writeFileSync(mdOut, `${md.join('\n')}\n`);

console.log('Hero portrait 360 calibration generated.');
console.log(`Input cases: ${rows.length}`);
console.log(`Severe/extreme visual start: ${severe.recommended}px (feasible ${severe.feasibleMin}-${severe.feasibleMax}px)`);
console.log(`Bubble-visible visual start: ${visible.recommended}px (feasible ${visible.feasibleMin}-${visible.feasibleMax}px)`);
console.log(`Candidate CSS: ${path.relative(root, candidatePath)}`);
console.log(`JSON: ${path.relative(root, jsonOut)}`);
console.log(`Markdown: ${path.relative(root, mdOut)}`);
console.log('');
console.log('Next: npm run qa:hero:composition:portrait360:candidate');
